UPDATE agent_conversation
SET title = #{title},
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND status = 'ACTIVE'

UPDATE agent_conversation
SET status = 'DELETED',
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND status = 'ACTIVE'
